BEGIN;
SET search_path=labassist_student,public;
CREATE FUNCTION pg_temp.ok(label TEXT,condition BOOLEAN) RETURNS TEXT LANGUAGE plpgsql AS $$
BEGIN IF condition IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAILED: %',label; END IF; RETURN 'PASS: '||label; END $$;
SELECT pg_temp.ok('two isolated demo terms',(SELECT count(*)=2 FROM academic_terms WHERE seed_key IN ('DEMO_TERM','PREVIOUS_DEMO_TERM')));
SELECT pg_temp.ok('previous term ends before current term',(SELECT p.ends_on<c.starts_on FROM academic_terms p CROSS JOIN academic_terms c WHERE p.seed_key='PREVIOUS_DEMO_TERM' AND c.seed_key='DEMO_TERM'));
SELECT pg_temp.ok('current snapshot is day ten',(SELECT c.starts_on=(p.created_at AT TIME ZONE 'Asia/Hebron')::date-9 FROM academic_terms p CROSS JOIN academic_terms c WHERE p.seed_key='PREVIOUS_DEMO_TERM' AND c.seed_key='DEMO_TERM'));
SELECT pg_temp.ok('23 current teams',(SELECT count(*)=23 AND bool_and(p.status='IN_PROGRESS') FROM projects p JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='DEMO_TERM'));
SELECT pg_temp.ok('15 completed previous teams',(SELECT count(*)=15 AND bool_and(p.status='COMPLETED') FROM projects p JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='PREVIOUS_DEMO_TERM'));
SELECT pg_temp.ok('54 current students unchanged',(SELECT count(*)=54 AND bool_and(a.status='PENDING_ACTIVATION') FROM accounts a WHERE seed_key LIKE 'STU%'));
SELECT pg_temp.ok('35 previous students without live logins',(SELECT count(*)=35 AND bool_and(a.status='DISABLED' AND password_hash IS NULL) FROM accounts a WHERE seed_key LIKE 'PAST_STU%'));
SELECT pg_temp.ok('all students have unique eight digit IDs',(SELECT count(*)=89 AND count(DISTINCT university_number)=89 AND bool_and(university_number ~ '^[0-9]{8}$') FROM accounts WHERE role='STUDENT'));
SELECT pg_temp.ok('previous profiles and preferences present',(SELECT count(*)=35 FROM student_profiles p JOIN accounts a ON a.id=p.account_id WHERE a.seed_key LIKE 'PAST_STU%') AND (SELECT count(*)=35 FROM student_settings p JOIN accounts a ON a.id=p.account_id WHERE a.seed_key LIKE 'PAST_STU%'));
SELECT pg_temp.ok('previous teams have two or three members',(SELECT count(*)=15 AND bool_and(students BETWEEN 2 AND 3) FROM seed_team_overview WHERE team_key LIKE 'PAST_TEAM%'));
SELECT pg_temp.ok('current capacity stays 25 with two spaces',(SELECT team_capacity=25 AND current_teams=23 AND remaining_teams=2 FROM workshop_capacity_summary WHERE term_id=(SELECT id FROM academic_terms WHERE seed_key='DEMO_TERM')));
SELECT pg_temp.ok('previous capacity separate',(SELECT current_teams=15 AND remaining_teams=10 FROM workshop_capacity_summary WHERE term_id=(SELECT id FROM academic_terms WHERE seed_key='PREVIOUS_DEMO_TERM')));
SELECT pg_temp.ok('supervisor capacity valid per term',NOT EXISTS(SELECT 1 FROM project_supervisors ps JOIN projects p ON p.id=ps.project_id GROUP BY ps.supervisor_id,p.term_id HAVING count(*)>4));
SELECT pg_temp.ok('140 completed historical tasks',(SELECT count(*)=140 AND bool_and(t.status='DONE' AND t.completed_at::date BETWEEN term.starts_on AND term.ends_on AND NOT t.needs_help) FROM project_tasks t JOIN projects p ON p.id=t.project_id JOIN academic_terms term ON term.id=p.term_id WHERE term.seed_key='PREVIOUS_DEMO_TERM'));
SELECT pg_temp.ok('previous personal progress is 100',(SELECT count(*)=35 AND bool_and(s.progress_percent=100 AND s.total_tasks=4) FROM project_member_work_summary s JOIN projects p ON p.id=s.project_id JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='PREVIOUS_DEMO_TERM'));
SELECT pg_temp.ok('15 resolved historical issues',(SELECT count(*)=15 AND bool_and(i.status='RESOLVED' AND i.resolved_at::date BETWEEN term.starts_on AND term.ends_on AND team_member(i.resolved_by,p.id)) FROM project_issues i JOIN projects p ON p.id=i.project_id JOIN academic_terms term ON term.id=p.term_id WHERE term.seed_key='PREVIOUS_DEMO_TERM'));
SELECT pg_temp.ok('60 acquired historical BOM items',(SELECT count(*)=60 AND bool_and(b.supply_status='ACQUIRED' AND b.missing_quantity=0) FROM project_bom_summary b JOIN projects p ON p.id=b.project_id JOIN academic_terms term ON term.id=p.term_id WHERE term.seed_key='PREVIOUS_DEMO_TERM'));
SELECT pg_temp.ok('15 historical purchase records',(SELECT count(*)=15 AND bool_and(e.status='POSTED' AND e.purchased_on BETWEEN t.starts_on AND t.ends_on) FROM project_expenses e JOIN projects p ON p.id=e.project_id JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='PREVIOUS_DEMO_TERM'));
SELECT pg_temp.ok('historical amounts reconcile',(SELECT count(*)=15 AND bool_and(s.budget=300 AND s.spent=47 AND s.remaining=253) FROM project_finance_summary s JOIN projects p ON p.id=s.project_id JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='PREVIOUS_DEMO_TERM'));
SELECT pg_temp.ok('current activity stays light',(SELECT count(*)=54 AND count(*) FILTER(WHERE t.status='DONE')=3 AND count(*) FILTER(WHERE t.status='IN_PROGRESS')=3 AND count(*) FILTER(WHERE t.status='TODO')=48 FROM project_tasks t JOIN projects p ON p.id=t.project_id JOIN academic_terms term ON term.id=p.term_id WHERE term.seed_key='DEMO_TERM'));
SELECT pg_temp.ok('current spending not invented',(SELECT count(*)=0 FROM project_expenses e JOIN projects p ON p.id=e.project_id JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='DEMO_TERM'));
SELECT pg_temp.ok('current BOM remains planning data',(SELECT count(*)=92 AND bool_and(b.supply_status='NEEDED') FROM project_bom_summary b JOIN projects p ON p.id=b.project_id JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='DEMO_TERM'));
SELECT pg_temp.ok('no extra current issues',(SELECT count(*)=3 AND bool_and(i.status='OPEN') FROM project_issues i JOIN projects p ON p.id=i.project_id JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='DEMO_TERM'));
SELECT pg_temp.ok('all backfill guards restored',(SELECT count(*)=3 AND bool_and(tgenabled='O') FROM pg_trigger WHERE (tgrelid='project_tasks'::regclass AND tgname='work_guard') OR (tgrelid='project_issues'::regclass AND tgname='work_guard') OR (tgrelid='project_students'::regclass AND tgname='membership_window')));
SELECT pg_temp.ok('155 historical work creation events',(SELECT count(*)=155 FROM project_work_events e JOIN projects p ON p.id=e.project_id JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='PREVIOUS_DEMO_TERM'));
SELECT pg_temp.ok('six current task progress events',(SELECT count(*)=6 FROM project_work_events e JOIN projects p ON p.id=e.project_id JOIN academic_terms t ON t.id=p.term_id WHERE t.seed_key='DEMO_TERM' AND e.event_key='UPDATED'));
SELECT pg_temp.ok('no passwords or raw invites added',(SELECT count(*)=0 FROM accounts WHERE password_hash IS NOT NULL) AND (SELECT count(*)=0 FROM activation_invitations));
ROLLBACK;
